{
  "items": [
    {
      "title": "European Social Survey (ESS) Round 10, 2020–2022",
      "url_or_doi": "https://ess.sikt.no/en/series/321b06ad-1b98-4b7d-93ad-ca8a24e8788a/853?tab=overview",
      "justification": "A major cross-national survey covering political behaviour, political participation, voting, party identification, political trust, satisfaction with democracy, immigration attitudes, social values, and institutional confidence. Round 10 collected data during 2020–2022 across approximately 30 European countries, including many EU member states and several non-EU European countries. Particularly suitable for comparing political attitudes across countries during the COVID-19 period. Individual-level microdata and documentation are available through the ESS Data Portal."
    },
    {
      "title": "European Social Survey (ESS) Round 11, 2023–2024",
      "url_or_doi": "https://ess.sikt.no/en/series/321b06ad-1b98-4b7d-93ad-ca8a24e8788a/853?tab=overview",
      "justification": "Cross-national survey containing individual-level information about electoral participation, political interest, party affiliation, trust in politicians and institutions, satisfaction with democracy, immigration, national identity, and social attitudes. Round 11 provides observations from 28 participating European countries, making it particularly useful for examining political attitudes and behaviour in the middle of the 2020s. The data can be compared with Round 10 to investigate changes over time."
    },
    {
      "title": "European Parliament Election Study 2024 – Voter Study",
      "url_or_doi": "https://doi.org/10.4232/1.14409",
      "justification": "A highly relevant comparative dataset examining voting behaviour and political attitudes following the June 2024 European Parliament elections. Covers all 27 EU member states listed in the query, including Belgium, Bulgaria, Czech Republic, Denmark, Germany, Estonia, Ireland, Greece, Spain, France, Italy, Cyprus, Latvia, Lithuania, Luxembourg, Hungary, Malta, Netherlands, Austria, Poland, Portugal, Romania, Slovenia, Slovakia, Finland, Sweden, and Croatia. Includes information about electoral choices, political preferences, perceptions of EU institutions, and evaluations of political representation. Especially appropriate for research on European electoral behaviour in 2024."
    },
    {
      "title": "Comparative Study of Electoral Systems (CSES) Module 6: Representative Democracy Under Pressure, 2021–2026",
      "url_or_doi": "https://cses.org/data-download/cses-module-6-2021-2026/",
      "justification": "International comparative election survey specifically designed to investigate political behaviour, democratic attitudes, electoral participation, and political representation. Its questionnaire addresses satisfaction with democracy, political trust, attitudes toward democratic institutions, electoral choices, and support for alternative forms of government. The November 17, 2026 advance release includes relevant election studies from Austria, Belgium, Denmark, France, Germany, Hungary, Lithuania, Montenegro, North Macedonia, Poland, Portugal, Slovakia, Slovenia, Spain, Sweden, and the United Kingdom, among others. Particularly useful for comparing EU and non-EU European democracies."
    },
    {
      "title": "Comparative Study of Electoral Systems (CSES) Module 5: Democracy Divided? 2016–2021",
      "url_or_doi": "https://cses.org/data-download/cses-module-5-2016-2021/",
      "justification": "Cross-national electoral survey examining voting behaviour, political participation, party preferences, political elites, populist attitudes, and perceptions of social and political divisions. Includes election studies conducted during 2020–2021 in countries such as Czech Republic, Germany, Lithuania, and the Netherlands. Although the module begins before 2020, its later observations provide relevant evidence about political attitudes and electoral behaviour during the early 2020s. Useful for examining relationships between political distrust, populism, and electoral choices."
    },
    {
      "title": "Standard and Special Eurobarometer Surveys, 2020–2026",
      "url_or_doi": "https://www.gesis.org/en/eurobarometer-data-service/data-and-documentation/standard-special-eb/study-overview",
      "justification": "An extensive collection of harmonized public opinion surveys conducted across European Union member states. Includes repeated measurements of political trust, confidence in national governments and parliaments, perceptions of democracy, European identity, EU membership attitudes, policy priorities, and satisfaction with political institutions. The archive contains numerous surveys from 2020 through 2026, enabling longitudinal and cross-national analysis. Particularly valuable because it covers all 27 EU countries in the query and provides downloadable individual-level survey data."
    },
    {
      "title": "Eurobarometer 101.3, April–May 2024",
      "url_or_doi": "https://search.gesis.org/research_data/ZA8843",
      "justification": "A harmonized Eurobarometer survey conducted in April and May 2024. Provides comparative public opinion data collected across EU member states during an important European election year. Relevant for studying attitudes toward European institutions, public policy, and political developments. The dataset is archived by GESIS and can be used alongside other Eurobarometer waves to examine changes in political attitudes across the EU during the 2020s."
    },
    {
      "title": "Standard Eurobarometer 104, Autumn 2025",
      "url_or_doi": "https://europa.eu/eurobarometer/surveys/detail/3378",
      "justification": "European Commission public opinion survey examining citizens' views on the European Union, economic conditions, European integration, and major political and societal concerns. Covers EU member states and offers comparative indicators relevant to political attitudes and institutional confidence. Particularly useful for analyzing public attitudes during 2025 and comparing them with previous Eurobarometer surveys conducted since 2020."
    },
    {
      "title": "European Parliament Eurobarometer, Autumn 2025",
      "url_or_doi": "https://europa.eu/eurobarometer/surveys/detail/3632",
      "justification": "A European Parliament public opinion survey examining attitudes toward EU membership, European political institutions, security, international conflicts, disinformation, and European cooperation. Provides country-level comparisons across the 27 EU member states. Relevant for investigating support for European integration, political priorities, and perceptions of democratic representation during the 2020s."
    },
    {
      "title": "European Values Study and World Values Survey: Joint EVS/WVS Dataset, 2017–2022",
      "url_or_doi": "https://www.gesis.org/en/european-values-study/data-and-documentation/joint-evs/wvs-2017-2022-dataset",
      "justification": "A harmonized international dataset combining European Values Study and World Values Survey observations. Covers numerous European countries, including EU member states, Western Balkan countries, Turkey, Moldova, and Georgia where participating surveys are available. Contains questions about political trust, confidence in government, attitudes toward democracy, political participation, ideological orientations, national identity, and social values. Some participating surveys were conducted during 2020–2022, making the dataset relevant to the early 2020s. Country-specific fieldwork dates should be checked because not all observations were collected after 2019."
    },
    {
      "title": "World Values Survey Wave 7, 2017–2022",
      "url_or_doi": "https://doi.org/10.14281/18241.18",
      "justification": "International public opinion dataset examining political values, democratic legitimacy, political participation, institutional trust, authoritarian attitudes, and social beliefs. Includes surveys from European and neighbouring countries, with some observations collected during 2020–2022. Particularly useful for comparing political attitudes in countries such as Turkey, Georgia, and other participating European states with wider international patterns. Provides individual-level survey microdata and standardized questionnaires. Researchers should select countries whose fieldwork occurred during the 2020s."
    },
    {
      "title": "World Values Survey Longitudinal Dataset, 1981–2022",
      "url_or_doi": "https://doi.org/10.14281/18241.17",
      "justification": "Harmonized longitudinal compilation of World Values Survey data that includes observations from the early 2020s. Measures confidence in political institutions, democratic preferences, political interest, civic engagement, political ideology, and social attitudes. Particularly valuable for placing political behaviour and attitudes observed during 2020–2022 into a longer historical context. Country-specific fieldwork years must be checked before selecting observations for the requested period."
    },
    {
      "title": "Integrated Values Surveys and European Values Study Data Collections",
      "url_or_doi": "https://www.gesis.org/en/european-values-study/data-and-documentation",
      "justification": "Provides access to harmonized European Values Study datasets and integrated international values survey collections covering multiple European countries. Relevant variables include confidence in parliament, political interest, democratic values, ideological identification, civic engagement, institutional legitimacy, and social attitudes. Some integrated collections include observations through 2022. Useful for comparative research involving both EU and non-EU European countries, although individual survey years and country participation vary."
    },
    {
      "title": "Balkan Barometer Public Opinion Survey 2020–2025",
      "url_or_doi": "https://www.rcc.int/balkanbarometer/results/2/public",
      "justification": "One of the most directly relevant sources for the Western Balkan countries in the query. The Regional Cooperation Council provides annual public opinion microdata for Albania, Bosnia and Herzegovina, Kosovo, Montenegro, North Macedonia, and Serbia. Surveys cover trust in institutions, perceptions of corruption, attitudes toward EU integration, regional cooperation, economic and political conditions, public policy priorities, and social attitudes. Individual-level datasets are available for each year from 2020 through 2025, enabling cross-country and longitudinal comparisons."
    },
    {
      "title": "Balkan Barometer Public Opinion 2024",
      "url_or_doi": "https://www.rcc.int/pubs/203/balkan-barometer-public-opinion-2024",
      "justification": "A regional survey conducted in March and April 2024 across Albania, Bosnia and Herzegovina, Kosovo, Montenegro, North Macedonia, and Serbia. The public opinion component surveyed approximately 6,000 respondents. It examines political and socioeconomic perceptions, institutional confidence, European integration, regional relations, and citizens' expectations. Particularly suitable for comparing political attitudes among the six Western Balkan economies in a single survey year."
    },
    {
      "title": "Balkan Barometer Public Opinion 2025",
      "url_or_doi": "https://www.rcc.int/balkanbarometer/home",
      "justification": "The 2025 edition of the Regional Cooperation Council's annual Western Balkans public opinion survey. Covers Albania, Bosnia and Herzegovina, Kosovo, Montenegro, North Macedonia, and Serbia. Provides recent information on public attitudes toward governance, regional cooperation, European integration, institutional confidence, and socioeconomic conditions. Microdata are accessible through the Balkan Barometer results database. Useful for examining political attitude trends across the Western Balkans between 2020 and 2025."
    },
    {
      "title": "European Observatory of Political Trust – Comparative Political Trust Database, 1980–2023",
      "url_or_doi": "https://trustobservatory.eu/wp/?page_id=394",
      "justification": "A specialized comparative dataset focusing on political trust across 44 European countries. Combines information from major survey programmes including Eurobarometer, European Social Survey, European Values Study, and World Values Survey. Includes measures of trust in political institutions alongside contextual information about electoral systems, corruption, democratic institutions, electoral participation, and political fragmentation. Contains data through 2023, making it especially valuable for studying political trust and its determinants during the early 2020s. Country and year availability differ across indicators."
    },
    {
      "title": "International Social Survey Programme (ISSP) 2023 – National Identity and Citizenship",
      "url_or_doi": "https://issp.org/news/publication-of-the-international-data-release-issp-2023-national-identity-citizenship/",
      "justification": "An international comparative survey examining national identity, citizenship, social belonging, and attitudes relevant to democratic participation and political communities. The 2023 module offers standardized questions suitable for comparing political and civic orientations across participating European countries. Particularly useful for studying relationships between national identity, citizenship norms, political integration, and public attitudes. Coverage is limited to participating ISSP countries rather than every country in the query."
    },
    {
      "title": "International Republican Institute – Western Balkans Regional Opinion Polls, 2020s",
      "url_or_doi": "https://www.iri.org/polls/",
      "justification": "Collection of public opinion polling studies covering political attitudes in Albania, Bosnia and Herzegovina, Kosovo, Montenegro, North Macedonia, and Serbia. Includes regional polling conducted during the 2020s, including a Western Balkans regional poll in 2025. Relevant topics include political preferences, confidence in institutions, democratic governance, international relations, corruption, and public policy priorities. Particularly useful for supplementing Balkan Barometer data with additional survey measures. Publicly accessible materials may consist of reports and aggregated results rather than downloadable respondent-level microdata."
    },
    {
      "title": "International Republican Institute – Moldova National Opinion Polls, 2020s",
      "url_or_doi": "https://www.iri.org/polls/",
      "justification": "Public opinion polling archive that includes national surveys conducted in the Republic of Moldova during the 2020s, including polling from May–June 2024. Relevant measures include political preferences, perceptions of national political developments, institutional confidence, electoral attitudes, and geopolitical orientations. Particularly valuable because Moldova is not consistently covered by EU-focused survey programmes. Availability of individual-level microdata should be verified; published polling results are more readily accessible."
    },
    {
      "title": "World Values Survey Wave 7 – Country-Level Data and Documentation",
      "url_or_doi": "https://www.worldvaluessurvey.org/WVSContents.jsp?CMSID=Documentation",
      "justification": "Official World Values Survey repository providing country-level survey datasets, questionnaires, technical reports, and cross-national files. Useful for identifying political attitude surveys in Georgia, Turkey, Moldova, and participating European countries. Political measures include democratic preferences, institutional trust, political participation, ideological orientations, and attitudes toward political authority. The repository allows researchers to identify the exact fieldwork periods and select surveys collected during 2020–2022."
    },
    {
      "title": "Eurobarometer 2020–2026 Individual-Level Microdata Archive",
      "url_or_doi": "https://www.gesis.org/en/eurobarometer-data-service/data-and-documentation",
      "justification": "GESIS repository providing standardized individual-level Eurobarometer datasets, questionnaires, methodological documentation, and survey metadata. Especially suitable for examining political trust, satisfaction with democracy, attitudes toward European institutions, policy preferences, and public perceptions of political developments across EU member states. Contains numerous surveys conducted throughout the 2020s. The archive supports repeated cross-sectional analysis and comparisons across European countries and survey years."
    },
    {
      "title": "European Commission Eurobarometer – Standard and Special Public Opinion Surveys",
      "url_or_doi": "https://europa.eu/eurobarometer/surveys",
      "justification": "Official European Commission survey catalogue containing repeated cross-national public opinion studies covering the 27 EU member states. Provides access to surveys addressing political priorities, confidence in institutions, attitudes toward European integration, democracy, migration, security, and societal challenges. Particularly useful for identifying topic-specific datasets from 2020 onward. The collection complements GESIS microdata by providing official survey documentation, reports, and country-level results."
    },
    {
      "title": "Comparative Study of Electoral Systems – Module 6 Third Advance Release, November 2026",
      "url_or_doi": "https://doi.org/10.7804/cses.module6.2026-11-17",
      "justification": "A specific, citable release of the CSES Module 6 comparative electoral dataset, published on November 17, 2026. Provides harmonized individual-level electoral survey observations from multiple democracies, including European countries within the requested geographical scope. Contains measures of voting behaviour, turnout, political trust, satisfaction with democracy, evaluations of representation, political attitudes, and democratic preferences. Especially useful for researchers requiring a stable dataset version with standardized variables and documentation for comparative electoral analysis."
    }
  ]
}
